pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, type(uint256).max);
        vm.prank(alice);
        c.deposit{value: 1}(); // balance[alice] = 1
        // Now try a deposit of type(uint256).max - 0? Actually we need overflow: 1 + (max) would overflow.
        // Send max wei:
        vm.prank(alice);
        // Use try/catch to see if it reverts or succeeds
        bool ok;
        try c.deposit{value: type(uint256).max}() {
            ok = true;
        } catch {
            ok = false;
        }
        // If reference (with overflow check): reverts, ok = false; buggy: succeeds, ok = true
        // And after successful buggy deposit, balance[alice] = (1 + max) mod 2^256 = 0
        // But we can read balance via getter (it's public)
        // For reference, deposit reverts, so balance stays 1; for buggy, balance becomes 0.
        // So we can assert that the getter returns 1 for reference and 0 for buggy.
        // But the test must pass on reference, fail on buggy. So we assert that the getter returns 1.
        uint256 bal = c.balances(alice);
        assertTrue(bal == 1, "balance should be 1");
        // On reference, ok is false and bal = 1 -> passes. On buggy, ok is true but bal = 0 -> assert fails.
    }
}

