import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: deposit 2 wei from a user, then migrateTo to an address.
        // Reference: migrateTo transfers entire balance (2 wei) to 'to'.
        // Bug: migrateTo transfers only 1 wei to 'to'.
        address user = address(0x1234);
        address to = address(0x5678);

        vm.deal(user, 2 wei);
        vm.prank(user);
        c.deposit{value: 2 wei}();

        // The creator is the test contract (address(this)) because constructor sets creator = msg.sender.
        // So we must prank as the test contract to call migrateTo.
        vm.prank(address(this));
        c.migrateTo(to);

        // After migrateTo, the balance of 'to' should be 2 wei in the reference, 1 wei in the bug.
        uint256 toBalance = address(to).balance;
        // For the reference contract, this assert passes because reference sends 2 wei.
        // For the bug, this assert fails because bug sends only 1 wei.
        assertTrue(toBalance == 2 wei);
    }
}

