pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, creator deposits 1 ether
        vm.deal(address(0x0), 1 ether);
        vm.prank(address(0x0));
        c.deposit{value: 1 ether}();
        // Now, a non-creator attempts to call migrateTo
        address nonCreator = address(0x1);
        vm.deal(nonCreator, 1 wei);
        vm.prank(nonCreator);
        // In the correct version, this should revert; in the buggy version it will succeed
        // We use a try/catch to capture revert difference
        bool success;
        try c.migrateTo(nonCreator) {
            success = true;
        } catch {
            success = false;
        }
        // Assert that the contract balance after the call is zero if migrateTo succeeded (buggy version) or non-zero if it reverted (correct version).
        // We assert that the correct contract would have non-zero balance (since it reverted), and the buggy would have zero.
        // For the test to pass on correct and fail on buggy, we assert that success is false (revert) and address(c).balance > 0.
        assertTrue(!success && address(c).balance > 0);
    }
}

